#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> (replaced_list: Vec<i32>)
    requires
        first.len() >= 1,
    ensures
        // Length is (first without last) + (second)
        replaced_list@.len() == (first@.len() - 1) + second@.len(),
        // Prefix from first (excluding last) is preserved
        forall|i: int|
            0 <= i < first@.len() - 1 ==> replaced_list@[i] == first@[i],
        // Entire second is appended after that prefix
        forall|j: int|
            0 <= j < second@.len() ==> replaced_list@[ (first@.len() - 1) + j ] == second@[j],
{
    // first is guaranteed non-empty, so first.len() - 1 is safe.
    let prefix_len = first.len() - 1;

    // Preallocate exact capacity: (first without last) + (all of second).
    let mut replaced_list = Vec::with_capacity(prefix_len + second.len());

    // Take all elements of first except the last.
    replaced_list.extend_from_slice(&first[..prefix_len]);

    // Append all elements of second in order.
    replaced_list.extend_from_slice(&second[..]);

    // Helpful facts tying exec lengths to spec lengths.
    assert(prefix_len as int == first@.len() - 1);
    assert(replaced_list@.len() == (first@.len() - 1) + second@.len());

    replaced_list
}

} // verus!

